DROP POLICY IF EXISTS "Admins can update user profiles" ON user_profiles;

CREATE POLICY "Admins can view all support tickets" ON support_tickets FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true));
CREATE POLICY "Admins can update any support ticket" ON support_tickets FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true)) WITH CHECK (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true));
CREATE POLICY "Admins can view all ticket messages" ON ticket_messages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true));
CREATE POLICY "Admins can reply to any ticket" ON ticket_messages FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true));
