CREATE POLICY "Admins can create FAQ articles" ON faq_articles FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true));
CREATE POLICY "Admins can delete FAQ articles" ON faq_articles FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM user_profiles WHERE user_profiles.id = auth.uid() AND user_profiles.is_admin = true));
